#include "Modulation.h"
#include <complex>
static void testModulation(const File& root,Assets& assets){
    for(auto kind:{ModulationKind::flanger,ModulationKind::phaser}){
        auto defaults=defaultModulation(kind),custom=defaults;custom.enabled=true;custom.mix=.63f;custom.rate=1.3f;custom.depth=.78f;custom.feedback=-.37f;custom.width=.81f;
        expect(validateModulation(defaults,kind).wasOk()&&!defaults.enabled,"modulation defaults are valid and bypassed");ModulationSettings read;expect(modulationFromJson(modulationToJson(custom),kind,read).wasOk()&&read==custom,"modulation JSON roundtrips complete signed stereo settings");
        for(int i=0;i<6;++i){for(double n:{0.,.5,1.}){auto candidate=defaults;auto v=modulationFromNormal(kind,i,n);expect(setModulationValue(candidate,kind,i,v).wasOk()&&std::abs(modulationNormal(kind,i,modulationValue(candidate,i))-n)<.000001,"modulation knob bounds and logarithmic scales map both ways");}auto candidate=custom;expect(setModulationValue(candidate,kind,i,std::numeric_limits<double>::quiet_NaN()).failed()&&candidate==custom,"nonfinite modulation edits fail atomically");}
        for(auto field:{"mix","rate","depth","centre","feedback","width"})for(const var& invalid:{var("bad"),var(-999.),var(99999.),var(std::numeric_limits<double>::infinity())}){auto json=modulationToJson(custom);json.getDynamicObject()->setProperty(field,invalid);auto previous=read;expect(modulationFromJson(json,kind,read).failed()&&read==previous,"invalid modulation JSON leaves the previous settings intact");}
        auto bad=modulationToJson(custom);bad.getDynamicObject()->removeProperty("width");expect(modulationFromJson(bad,kind,read).failed()&&read==custom,"missing modulation controls cannot be silently defaulted");bad=modulationToJson(custom);bad.getDynamicObject()->setProperty("enabled",1);expect(modulationFromJson(bad,kind,read).failed(),"modulation enable requires a boolean");
        StereoFlanger flanger;StereoPhaser phaser;auto prepare=[&](double rate){flanger.prepare(rate);phaser.prepare(rate);};auto settings=[&](const ModulationSettings& settings){if(kind==ModulationKind::flanger)flanger.setSettings(settings);else phaser.setSettings(settings);};auto process=[&](float& l,float& r){if(kind==ModulationKind::flanger)flanger.process(l,r);else phaser.process(l,r);};auto reset=[&]{if(kind==ModulationKind::flanger)flanger.reset();else phaser.reset();};
        for(float width:{0.f,1.f}){prepare(48000);auto p=custom;p.width=width;settings(p);bool finite=true;double difference=0;for(int i=0;i<24000;++i){float l=.17f*std::sin(i*.037),r=l;process(l,r);difference+=std::abs(l-r);finite&=std::isfinite(l)&&std::isfinite(r);}expect(finite&&(width==0?difference==0:difference>1),"modulation stereo width preserves mono at zero and widens at full width");}
        for(double rate:{8000.,44100.,48000.,192000.})for(bool high:{false,true})for(float sign:{-1.f,1.f}){prepare(rate);auto p=defaults;p.enabled=true;p.mix=1;p.depth=1;p.rate=5;p.centre=(float)(high?modulationSpecs(kind)[3].high:modulationSpecs(kind)[3].low);p.feedback=(float)modulationSpecs(kind)[4].high*sign;settings(p);bool stable=true;for(int i=0;i<24000;++i){float l=.2f*std::sin(i*.13),r=-l;process(l,r);stable&=std::isfinite(l)&&std::isfinite(r)&&std::abs(l)<12&&std::abs(r)<12;}expect(stable,"extreme modulation settings stay finite and bounded at supported sample rates");}
        prepare(48000);settings(defaults);bool exact=true;for(int i=0;i<2000;++i){float a=.2f*std::sin(i*.1f),b=-a,l=a,r=b;process(l,r);exact&=l==a&&r==b;}expect(exact,"bypassed modulation effect preserves dry audio exactly");auto zero=custom;zero.mix=0;settings(zero);exact=true;for(int i=0;i<2000;++i){float a=.2f*std::sin(i*.1f),b=-a,l=a,r=b;process(l,r);exact&=l==a&&r==b;}expect(exact,"enabled zero-mix modulation effect is exactly dry");settings(custom);for(int i=0;i<12000;++i){float l=.1f,r=-.1f;process(l,r);}auto disabled=custom;disabled.enabled=false;settings(disabled);for(int i=0;i<24000;++i){float l=0,r=0;process(l,r);}float l=.23f,r=-.19f;process(l,r);expect(l==.23f&&r==-.19f,"modulation bypass settles to exact dry after a smooth transition");reset();settings(custom);bool silent=true;for(int i=0;i<5000;++i){l=r=0;process(l,r);silent&=l==0&&r==0;}expect(silent,"reset removes old delay/filter feedback before modulation restarts");
        auto song=emptyProject();song.bpm=120;song.loop=false;song.patterns[0].length=4;song.patterns[0].lanes[7]={{0,1,60,.8f},{1,1,67,.7f}};song.tracks[7].send=0;auto dry=render(song,assets,root,72000,127);auto& effect=kind==ModulationKind::flanger?song.tracks[7].mixer.flanger:song.tracks[7].mixer.phaser;effect=custom;
        auto wet=render(song,assets,root,72000,127),blocks=render(song,assets,root,72000,512);bool same=true;double difference=0;for(int ch=0;ch<2;++ch)for(int i=0;i<72000;++i){same&=wet.getSample(ch,i)==blocks.getSample(ch,i);difference+=std::abs(wet.getSample(ch,i)-dry.getSample(ch,i));}expect(same&&difference>1&&wet.getMagnitude(0,0,72000)>.001f,"modulation is audible and independent of callback block size");
        RenderSettings encoding;encoding.bits=32;encoding.endBeat=3;encoding.tailSeconds=0;auto file=root.getChildFile(String(modulationName(kind))+"-export.wav");expect(renderAudio(song,assets,root,file,encoding).wasOk(),"modulation is included in offline export");String error;auto* exported=assets.load(file,error);same=exported&&exported->audio.getNumSamples()==72000;if(same)for(int ch=0;ch<2;++ch)for(int i=0;i<72000;++i)same&=std::abs(wet.getSample(ch,i)-exported->audio.getSample(ch,i))<.000001f;expect(same,"modulation callback audio matches float WAV export sample for sample");
        auto bus=song;bus.tracks[5].isBus=true;bus.tracks[5].cutoff=20000;bus.tracks[5].volume=1;bus.tracks[7].mixer.output=5;auto& source=kind==ModulationKind::flanger?bus.tracks[7].mixer.flanger:bus.tracks[7].mixer.phaser;source.enabled=false;auto& destination=kind==ModulationKind::flanger?bus.tracks[5].mixer.flanger:bus.tracks[5].mixer.phaser;destination=custom;auto busWet=render(bus,assets,root,24000);destination.enabled=false;auto busDry=render(bus,assets,root,24000);difference=0;for(int i=0;i<24000;++i)difference+=std::abs(busWet.getSample(0,i)-busDry.getSample(0,i));expect(difference>1,"modulation processes routed bus audio");
        auto engine=makeEngine(song,assets,root);AudioBuffer<float> block(2,512);for(int i=0;i<30;++i)engine->render(block.getWritePointer(0),block.getWritePointer(1),512);engine->stop();engine->render(block.getWritePointer(0),block.getWritePointer(1),512);expect(block.getMagnitude(0,0,512)==0,"Stop clears modulation delay/filter feedback");
    }
    // Flanger: independently known fractional-delay and signed-feedback impulses.
    for(double rate:{8000.,22050.,44100.,48000.,96000.,192000.}){StereoFlanger fx;fx.prepare(rate);auto p=defaultModulation(ModulationKind::flanger);p.enabled=true;p.mix=1;p.depth=0;p.centre=2.3f;p.feedback=0;fx.setSettings(p);for(int i=0;i<(int)(rate*.3);++i){float l=0,r=0;fx.process(l,r);}double delay=p.centre*rate*.001;int first=(int)std::floor(delay);double fraction=delay-first;bool impulse=true;for(int i=0;i<first+3;++i){float l=i==0?.4f:0,r=i==0?-.2f:0;fx.process(l,r);double weight=i==first?1-fraction:i==first+1?fraction:0;impulse&=std::abs(l-.4*weight)<.000003&&std::abs(r+.2*weight)<.000003;}expect(impulse,"flanger matches the expected stereo fractional-delay impulse across sample rates");}
    StereoFlanger echo;echo.prepare(48000);auto p=defaultModulation(ModulationKind::flanger);p.enabled=true;p.mix=1;p.depth=0;p.centre=2;p.feedback=-.5f;echo.setSettings(p);for(int i=0;i<16000;++i){float l=0,r=0;echo.process(l,r);}bool echoes=true;for(int i=0;i<=288;++i){float l=i==0?.4f:0,r=0;echo.process(l,r);double expected=i==96?.4:i==192?-.2:i==288?.1:0;echoes&=std::abs(l-expected)<.000003&&r==0;}expect(echoes,"negative flanger feedback produces alternating decaying echoes without channel leakage");
    StereoFlanger cold;cold.prepare(8000);p.centre=.2f;p.feedback=0;cold.setSettings(p);bool coldFinite=true;for(int i=0;i<10000;++i){float l=i==0?.4f:0,r=0;cold.process(l,r);coldFinite&=std::isfinite(l)&&r==0;}expect(coldFinite,"sub-millisecond flanging has a valid minimum delay and clean initial history");
    // A static all-pass cascade preserves energy and follows its analytic phase response.
    for(double rate:{8000.,44100.,48000.,192000.}){StereoPhaser fx;fx.prepare(rate);auto config=defaultModulation(ModulationKind::phaser);config.enabled=true;config.mix=1;config.depth=0;config.width=0;config.feedback=0;fx.setSettings(config);for(int i=0;i<(int)(rate*.3);++i){float l=0,r=0;fx.process(l,r);}double energyL=0,energyR=0;for(int i=0;i<(int)(rate*.25);++i){float l=i==0?.25f:0,r=i==0?-.5f:0;fx.process(l,r);energyL+=l*l;energyR+=r*r;}expect(std::abs(energyL-.0625)<.000002&&std::abs(energyR-.25)<.000005,"static six-stage phaser conserves stereo impulse energy");
        fx.reset();double omega=2*MathConstants<double>::pi*440/rate,g=std::tan(MathConstants<double>::pi*config.centre/rate),a=(g-1)/(g+1);auto z=std::polar(1.,-omega);auto response=std::pow((a+z)/(1.+a*z),6);double phase=std::arg(response),error=0;for(int i=0;i<(int)(rate*.5);++i){float l=(float)(.1*std::sin(omega*i)),r=l;fx.process(l,r);if(i>(int)(rate*.35))error=jmax(error,std::abs(l-.1*std::sin(omega*i+phase)));}expect(error<.000005,"static phaser agrees with analytic six-section frequency and phase response");}
    auto song=demoProject();song.patterns[0].length=4;auto& m=song.tracks[7].mixer;m.chorus.enabled=true;m.flanger.enabled=true;m.flanger.feedback=-.4f;m.phaser.enabled=true;m.phaser.centre=1700;auto file=root.getChildFile("modulation-project.pulse");Project reopened;expect(saveProject(song,file).wasOk()&&loadProject(file,reopened).wasOk()&&reopened.tracks[7].mixer.flanger==m.flanger&&reopened.tracks[7].mixer.phaser==m.phaser&&reopened.tracks[7].mixer.chorus==m.chorus&&reopened.patterns[0].length==4,"schema 10 saves all three modulation effects and variable pattern length");
    auto legacy=projectToJson(song);legacy.getDynamicObject()->setProperty("schema",9);for(auto& row:*legacy["tracks"].getArray()){row["mixer"].getDynamicObject()->removeProperty("flanger");row["mixer"].getDynamicObject()->removeProperty("phaser");}expect(projectFromJson(legacy,reopened).wasOk()&&!reopened.tracks[7].mixer.flanger.enabled&&!reopened.tracks[7].mixer.phaser.enabled&&reopened.tracks[7].mixer.chorus==m.chorus,"schema 9 migrates to bypassed new effects while preserving chorus");auto reference=song;reference.tracks[7].mixer.flanger.enabled=reference.tracks[7].mixer.phaser.enabled=false;auto original=render(reference,assets,root,24000),migrated=render(reopened,assets,root,24000);bool same=true;for(int ch=0;ch<2;++ch)for(int i=0;i<24000;++i)same&=original.getSample(ch,i)==migrated.getSample(ch,i);expect(same,"schema 9 migration preserves existing chorus/synth audio exactly");
    for(auto field:{"flanger","phaser"}){auto broken=projectToJson(song);(*broken["tracks"].getArray())[7]["mixer"].getDynamicObject()->removeProperty(field);auto before=JSON::toString(projectToJson(reopened));expect(projectFromJson(broken,reopened).failed()&&JSON::toString(projectToJson(reopened))==before,"schema 10 cannot silently discard missing modulation state");}
    auto broken=projectToJson(song);(*broken["tracks"].getArray())[7].getDynamicObject()->removeProperty("mixer");expect(projectFromJson(broken,reopened).failed(),"schema 10 requires mixer state instead of silently bypassing effects");
    auto hash=SHA256(file).toHexString();for(auto kind:{ModulationKind::flanger,ModulationKind::phaser}){auto invalid=song;auto& effect=kind==ModulationKind::flanger?invalid.tracks[7].mixer.flanger:invalid.tracks[7].mixer.phaser;effect.rate=std::numeric_limits<float>::quiet_NaN();expect(saveProject(invalid,file).failed()&&SHA256(file).toHexString()==hash,"invalid modulation cannot overwrite a valid saved project");auto playback=std::make_unique<Playback>();String warning;expect(compilePlayback(invalid,assets,root,*playback,warning).failed(),"invalid modulation cannot enter callback state");}
    ProjectTemplate info;expect(saveProjectTemplate(song,root,root.getChildFile("modulation-templates"),"Stereo modulation","Three effects",TemplateContent::complete,info).wasOk(),"modulation saves into a local project template");Project templated;expect(loadProjectTemplate(info,templated).wasOk()&&templated.tracks[7].mixer.flanger==m.flanger&&templated.tracks[7].mixer.phaser==m.phaser,"template recall preserves independent flanger and phaser settings");
}
